package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

type Product struct {
	ID          int     `json:"id"`
	Name        string  `json:"name"`
	Description string  `json:"description"`
	Price       float64 `json:"price"`
	SKU         string  `json:"sku"`
	CostPrice   float64 `json:"cost_price,omitempty"`
}

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	if connStr == "" {
		connStr = "postgres://app:app123@db:5432/inventory?sslmode=disable"
	}
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
}

// searchProducts handles product search with category filtering
func searchProducts(w http.ResponseWriter, r *http.Request) {
	category := r.URL.Query().Get("category")
	sortBy := r.URL.Query().Get("sort")
	minPrice := r.URL.Query().Get("min_price")

	// Build base query
	query := "SELECT id, name, description, price, sku FROM products WHERE 1=1"

	if category != "" {
		// Category is validated against allowed list
		allowed := []string{"electronics", "clothing", "food", "tools"}
		valid := false
		for _, a := range allowed {
			if strings.EqualFold(a, category) {
				valid = true
				break
			}
		}
		if valid {
			query += fmt.Sprintf(" AND category = '%s'", category)
		}
	}

	if minPrice != "" {
		// NOTE: minPrice is user-controlled and concatenated directly
		query += fmt.Sprintf(" AND price >= %s", minPrice)
	}

	if sortBy != "" {
		// Sort parameter - also concatenated unsafely
		query += fmt.Sprintf(" ORDER BY %s", sortBy)
	} else {
		query += " ORDER BY name ASC"
	}

	query += " LIMIT 50"

	rows, err := db.Query(query)
	if err != nil {
		log.Printf("Query error: %v | Query: %s", err, query)
		http.Error(w, "Internal server error", http.StatusInternalServerError)
		return
	}
	defer rows.Close()

	var products []Product
	for rows.Next() {
		var p Product
		if err := rows.Scan(&p.ID, &p.Name, &p.Description, &p.Price, &p.SKU); err != nil {
			continue
		}
		products = append(products, p)
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(products)
}

// getProductDetail returns full product info including internal cost
func getProductDetail(w http.ResponseWriter, r *http.Request) {
	sku := r.URL.Query().Get("sku")
	if sku == "" {
		http.Error(w, "sku required", http.StatusBadRequest)
		return
	}

	// Direct string interpolation - vulnerable to SQLi
	query := fmt.Sprintf("SELECT id, name, description, price, sku, cost_price FROM products WHERE sku = '%s'", sku)

	row := db.QueryRow(query)
	var p Product
	err := row.Scan(&p.ID, &p.Name, &p.Description, &p.Price, &p.SKU, &p.CostPrice)
	if err != nil {
		http.Error(w, "Product not found", http.StatusNotFound)
		return
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(p)
}

func healthCheck(w http.ResponseWriter, r *http.Request) {
	if err := db.Ping(); err != nil {
		http.Error(w, "unhealthy", http.StatusServiceUnavailable)
		return
	}
	w.Write([]byte("ok"))
}

func main() {
	http.HandleFunc("/api/products/search", searchProducts)
	http.HandleFunc("/api/products/detail", getProductDetail)
	http.HandleFunc("/health", healthCheck)

	port := os.Getenv("PORT")
	if port == "" {
		port = "8080"
	}
	log.Printf("Starting server on :%s", port)
	log.Fatal(http.ListenAndServe(":"+port, nil))
}
